<?php if($m): ?><div class="patient-page-heading"><div><span class="eyebrow text-secondary"><?= $escape($m['codigo_medico']) ?></span><h1><?= $escape($m['nombres'].' '.$m['apellidos']) ?></h1><p class="text-secondary">Horarios y bloqueos administrativos. No se muestran datos de pacientes.</p></div><a class="btn btn-clinic" href="/horarios/agenda?medico=<?= $escape($m['id_medico']) ?>">Consultar disponibilidad</a></div>
